async function fetchMarketCandles(apiBase,params,parentSignal){
 const entries=Object.entries(params).filter(([,v])=>v!==undefined&&v!==null);
 const query=new URLSearchParams(entries.map(([k,v])=>[k,String(v)]));
 const binanceQuery=new URLSearchParams(entries.map(([k,v])=>[k==="end_time"?"endTime":k,String(v)]));
 const sources=[{url:apiBase.replace(/\/$/,"")+"/market/candles?"+query,kind:"backend"},...BINANCE_REST_HOSTS.map(host=>({url:host+"/api/v3/klines?"+binanceQuery,kind:"binance"}))];
 let lastError=null;
 for(const source of sources){
  if(parentSignal?.aborted)throw new DOMException("Request cancelled","AbortError");
  const controller=new AbortController(),abortParent=()=>controller.abort();
  parentSignal?.addEventListener("abort",abortParent,{once:true});
  const timer=window.setTimeout(()=>controller.abort(),source.kind==="backend"?5000:7000);
  try{
   const response=await fetch(source.url,{cache:"no-store",signal:controller.signal,headers:{Accept:"application/json"}});
   const payload=await response.json().catch(()=>null);
   if(!response.ok)throw new Error(payload?.detail||"Market-data source returned HTTP "+response.status);
   let rows;
   if(source.kind==="binance"){
    if(!Array.isArray(payload))throw new Error("Binance returned an invalid candle payload.");
    rows=payload.map(row=>Array.isArray(row)?({time:Math.floor(Number(row[0])/1000),open:Number(row[1]),high:Number(row[2]),low:Number(row[3]),close:Number(row[4]),volume:Number(row[5]),close_time:Math.floor(Number(row[6]||row[0])/1000),quote_volume:Number(row[7]||0),trades:Number(row[8]||0),is_closed:Number(row[6]||0)<Date.now()}):null).filter(Boolean);
   }else{
    if(!Array.isArray(payload?.candles))throw new Error("Backend response is missing its candles array.");
    rows=payload.candles;
   }
   if(rows.length<2)throw new Error("Market-data source returned fewer than two candles.");
   return {candles:rows,provider:source.kind==="backend"?(payload.provider||"ZenCrypto market API"):"Binance public REST fallback"};
  }catch(error){
   if(parentSignal?.aborted)throw new DOMException("Request cancelled","AbortError");
   lastError=error;
  }finally{
   window.clearTimeout(timer);
   parentSignal?.removeEventListener("abort",abortParent);
  }
 }
 throw new Error("Unable to load live market candles from the API or Binance fallback. "+(lastError?.message||"Please retry."));
}


