 async function loadIndexedHistory(){const requestId=++indexedHistoryRequestRef.current;const requestedAddress=walletAddress;const requestedChain=walletChainId;if(!requestedAddress||!["0x1","0x2105"].includes(requestedChain)){setIndexedHistory([]);setIndexedLatestBlock(null);setIndexedHistoryError("Connect an Ethereum or Base mainnet wallet to view indexed history.");setIndexedHistoryBusy(false);return;}setIndexedHistoryBusy(true);setIndexedHistoryError("");try{const chainId=parseInt(requestedChain,16);const response=await fetch(API+"/chain/history?"+new URLSearchParams({chainId:String(chainId),address:requestedAddress,limit:"50"}));const data=await response.json().catch(()=>({detail:"Invalid history response"}));if(!response.ok)throw Error(data.detail||"History provider unavailable.");let latestBlock=null;const provider=getWalletProvider();if(provider){const activeChain=await provider.request({method:"eth_chainId"});if(activeChain===requestedChain){const blockHex=await provider.request({method:"eth_blockNumber"});latestBlock=Number.parseInt(blockHex,16);if(!Number.isSafeInteger(latestBlock)||latestBlock<0)latestBlock=null;}}if(requestId!==indexedHistoryRequestRef.current)return;setIndexedLatestBlock(latestBlock);const enriched=(data.items||[]).map(item=>{const raw=item.blockNumber;const block=typeof raw==="string"&&raw.startsWith("0x")?Number.parseInt(raw,16):Number(raw);const confirmations=latestBlock!==null&&Number.isSafeInteger(block)&&block>0&&block<=latestBlock?latestBlock-block+1:null;return {...item,confirmations};});setIndexedHistory(enriched);}catch(e){if(requestId===indexedHistoryRequestRef.current)setIndexedHistoryError(e.message||"Unable to load indexed history.");}finally{if(requestId===indexedHistoryRequestRef.current)setIndexedHistoryBusy(false);}}
